#!/usr/bin/env python3
"""COMMONWEAVE Zero — contract-driven ctypes adapter generator.

Reads a YAML/JSON contract and emits a Python module that loads the shared
library, validates preconditions declared in the contract, and exposes typed
wrappers. Glue LOC is intentionally minimal (generated, not hand-written).
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path
from typing import Any, Dict, List

try:
    import yaml
except ImportError:  # pragma: no cover
    yaml = None


TYPE_MAP = {
    "float64": "ctypes.c_double",
    "float32": "ctypes.c_float",
    "int32": "ctypes.c_int32",
    "int64": "ctypes.c_int64",
    "uint32": "ctypes.c_uint32",
    "uint64": "ctypes.c_uint64",
    "size_t": "ctypes.c_size_t",
    "int": "ctypes.c_int",
    "bool": "ctypes.c_bool",
}


def load_contract(path: Path) -> Dict[str, Any]:
    text = path.read_text(encoding="utf-8")
    if path.suffix.lower() in (".yaml", ".yml"):
        if yaml is None:
            raise RuntimeError("pyyaml required for YAML contracts: pip install pyyaml")
        return yaml.safe_load(text)
    return json.loads(text)


def _ctype(element: str) -> str:
    if element not in TYPE_MAP:
        raise ValueError(f"Unsupported element type in contract: {element}")
    return TYPE_MAP[element]


def emit_ctypes_adapter(contract: Dict[str, Any], lib_path: str) -> str:
    name = contract.get("name", "component")
    version = contract.get("version", "0.0.0")
    functions: List[Dict[str, Any]] = contract.get("functions") or []

    lines: List[str] = [
        f'"""AUTO-GENERATED by COMMONWEAVE Zero — do not edit by hand.',
        f'Contract: {name} v{version}',
        f'Library:  {lib_path}',
        '"""',
        "from __future__ import annotations",
        "",
        "import ctypes",
        "from pathlib import Path",
        "",
        f'_LIB_PATH = Path(r"{lib_path}")',
        "",
        "class CWError(Exception):",
        '    """Raised when the native component returns a non-zero error code."""',
        "    def __init__(self, code: int, message: str = \"\"):",
        "        self.code = code",
        "        super().__init__(message or f\"native error {code}\")",
        "",
        "_ERROR_MAP = {",
        '    0: "OK",',
        '    1: "NULL_POINTER",',
        '    2: "INVALID_DIMENSION",',
        '    3: "OVERFLOW",',
        '    4: "ALIGNMENT",',
        '    5: "VALUE_OUT_OF_RANGE",',
        "}",
        "",
        "def _load_lib() -> ctypes.CDLL:",
        "    if not _LIB_PATH.is_file():",
        "        raise FileNotFoundError(f\"Shared library not found: {_LIB_PATH}\")",
        "    return ctypes.CDLL(str(_LIB_PATH))",
        "",
        "_lib = _load_lib()",
        "",
    ]

    # Structs
    for st in contract.get("structs") or []:
        sname = st["name"]
        lines.append(f"class {sname}(ctypes.Structure):")
        lines.append("    _fields_ = [")
        for f in st.get("fields") or []:
            lines.append(f'        ("{f["name"]}", {_ctype(f["type"])}),')
        lines.append("    ]")
        lines.append("")

    for fn in functions:
        fname = fn["name"]
        params = fn.get("parameters") or []
        # Build argtypes
        argtypes = []
        for p in params:
            if p.get("type") == "pointer":
                elem = p.get("element", "float64")
                if elem in (contract.get("structs") or []) or any(
                    s.get("name") == elem for s in (contract.get("structs") or [])
                ):
                    argtypes.append(f"ctypes.POINTER({elem})")
                else:
                    argtypes.append(f"ctypes.POINTER({_ctype(elem)})")
            else:
                argtypes.append(_ctype(p.get("type", "int")))

        lines.append(f"# --- {fname} ---")
        lines.append(f"_lib.{fname}.argtypes = [")
        for a in argtypes:
            lines.append(f"    {a},")
        lines.append("]")
        lines.append(f"_lib.{fname}.restype = ctypes.c_int")
        lines.append("")

        # Function body — specialised safe patterns for known kernels, generic otherwise
        if fname == "matmul":
            lines += _emit_matmul()
        elif fname == "scale_clamp":
            lines += _emit_scale_clamp()
        elif fname == "array_stats":
            lines += _emit_array_stats()
        elif fname == "histogram":
            lines += _emit_histogram()
        else:
            lines += _emit_generic(fname, params)

    lines.append("# End of generated adapter")
    return "\n".join(lines)


def _emit_matmul() -> List[str]:
    return [
        "def matmul(A, B, C, m: int, k: int, n: int) -> None:",
        '    """C = A @ B (row-major float64). Raises CWError on native failure."""',
        "    if m < 1 or k < 1 or n < 1 or m > 10000 or k > 10000 or n > 10000:",
        '        raise CWError(2, "INVALID_DIMENSION")',
        "    if A is None or B is None or C is None:",
        '        raise CWError(1, "NULL_POINTER")',
        "    def to_c(buf, expected_len):",
        "        if hasattr(buf, '__len__') and len(buf) < expected_len:",
        "            raise CWError(2, f'buffer too short: need {expected_len}')",
        "        return (ctypes.c_double * expected_len)(*buf)",
        "    a_arr = to_c(A, m * k)",
        "    b_arr = to_c(B, k * n)",
        "    c_arr = (ctypes.c_double * (m * n))()",
        "    rc = _lib.matmul(a_arr, b_arr, c_arr, m, k, n)",
        "    if rc != 0:",
        '        raise CWError(rc, _ERROR_MAP.get(rc, "UNKNOWN"))',
        "    if hasattr(C, '__setitem__'):",
        "        for i in range(m * n):",
        "            C[i] = c_arr[i]",
        "    else:",
        "        return list(c_arr)",
        "    return None",
        "",
    ]


def _emit_scale_clamp() -> List[str]:
    return [
        "def scale_clamp(in_buf, out_buf, length: int, scale: float, lo: float, hi: float) -> None:",
        '    """out[i] = clamp(in[i] * scale, lo, hi). Requires hi >= lo."""',
        "    if length < 1:",
        '        raise CWError(2, "INVALID_DIMENSION")',
        "    if hi < lo:",
        '        raise CWError(2, "INVALID_DIMENSION")',
        "    if in_buf is None or out_buf is None:",
        '        raise CWError(1, "NULL_POINTER")',
        "    in_arr = (ctypes.c_double * length)(*in_buf)",
        "    out_arr = (ctypes.c_double * length)()",
        "    rc = _lib.scale_clamp(in_arr, out_arr, length, scale, lo, hi)",
        "    if rc != 0:",
        '        raise CWError(rc, _ERROR_MAP.get(rc, "UNKNOWN"))',
        "    for i in range(length):",
        "        out_buf[i] = out_arr[i]",
        "",
    ]


def _emit_array_stats() -> List[str]:
    return [
        "def array_stats(data, length: int):",
        '    """Return cw_stats structure for int32 buffer."""',
        "    if length < 1 or length > 1_000_000:",
        '        raise CWError(2, "INVALID_DIMENSION")',
        "    if data is None:",
        '        raise CWError(1, "NULL_POINTER")',
        "    arr = (ctypes.c_int32 * length)(*data)",
        "    out = cw_stats()",
        "    rc = _lib.array_stats(arr, length, ctypes.byref(out))",
        "    if rc != 0:",
        '        raise CWError(rc, _ERROR_MAP.get(rc, "UNKNOWN"))',
        "    return out",
        "",
    ]


def _emit_histogram() -> List[str]:
    return [
        "def histogram(data, length: int, lo: int, hi: int, nbins: int):",
        '    """Equal-width histogram over [lo, hi); returns list[int] of size nbins."""',
        "    if length < 1 or nbins < 1 or nbins > 4096 or hi <= lo:",
        '        raise CWError(2, "INVALID_DIMENSION")',
        "    if data is None:",
        '        raise CWError(1, "NULL_POINTER")',
        "    arr = (ctypes.c_int32 * length)(*data)",
        "    bins = (ctypes.c_uint32 * nbins)()",
        "    rc = _lib.histogram(arr, length, lo, hi, bins, nbins)",
        "    if rc != 0:",
        '        raise CWError(rc, _ERROR_MAP.get(rc, "UNKNOWN"))',
        "    return [int(bins[i]) for i in range(nbins)]",
        "",
    ]


def _emit_generic(fname: str, params: List[Dict[str, Any]]) -> List[str]:
    args_sig = ", ".join(p["name"] for p in params)
    return [
        f"def {fname}({args_sig}):",
        f'    """Generated wrapper for {fname}. Preconditions are enforced by the native side."""',
        "    # Generic path: caller supplies already-constructed ctypes arguments.",
        f"    rc = _lib.{fname}({args_sig})",
        "    if rc != 0:",
        '        raise CWError(rc, _ERROR_MAP.get(rc, "UNKNOWN"))',
        "    return rc",
        "",
    ]


def main() -> None:
    parser = argparse.ArgumentParser(description="COMMONWEAVE Zero adapter generator")
    parser.add_argument("--contract", required=True, type=Path)
    parser.add_argument("--lib", required=True, type=Path)
    parser.add_argument("--out", required=True, type=Path)
    args = parser.parse_args()
    contract = load_contract(args.contract)
    code = emit_ctypes_adapter(contract, str(args.lib.resolve()))
    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text(code, encoding="utf-8")
    print(f"Generated adapter: {args.out}")


if __name__ == "__main__":
    main()
